(()=>{function e(e){e&&window.goatcounter?.count&&window.goatcounter.count({path:`event/${e}`,title:e,event:!0})}document.querySelectorAll("[data-goat-event]").forEach(t=>{t.addEventListener("click",()=>e(t.dataset.goatEvent))}),document.querySelectorAll("[data-subscribe-form]").forEach(t=>{t.addEventListener("submit",()=>e("subscribe-attempt"))}),document.querySelectorAll("[data-share-url]").forEach(e=>{let t;const s=e.textContent;async function n(n){try{await navigator.clipboard.writeText(n),e.textContent="COPIED",clearTimeout(t),t=setTimeout(()=>{e.textContent=s},1600)}catch{window.prompt("Copy this link:",n)}}e.addEventListener("click",async()=>{const t=e.dataset.shareUrl,s=e.dataset.shareTitle||document.title;if(navigator.share)try{await navigator.share({title:s,url:t})}catch(e){e.name!=="AbortError"&&await n(t)}else await n(t)})})})()